replacements.new:
try:
    # OSHO_GLOBAL_UPLOAD_MIN_INTERVAL_V1
    # Serialize automated uploads and enforce a global
    # 29-minute minimum interval using durable public
    # YouTube receipts as the source of truth.
    import fcntl as _fcntl
    import time as _time

    _yt_state = Path(
        os.environ.get(
            "OSHO_YOUTUBE_STATE_DIR",
            "/data/youtube",
        )
    )
    _yt_receipts = _yt_state / "receipts"
    _yt_receipts.mkdir(
        parents=True,
        exist_ok=True,
    )
    _yt_lock_path = (
        _yt_receipts /
        ".global-upload.lock"
    )

    with _yt_lock_path.open("a+") as _yt_lock:
        _fcntl.flock(
            _yt_lock.fileno(),
            _fcntl.LOCK_EX,
        )

        _latest_public = None
        for _receipt_path in _yt_receipts.glob(
            "*.json"
        ):
            try:
                _receipt = json.loads(
                    _receipt_path.read_text(
                        encoding="utf-8",
                    )
                )
            except Exception:
                continue

            if not isinstance(_receipt, dict):
                continue
            if str(
                _receipt.get(
                    "privacy_status",
                    "",
                )
            ).lower() != "public":
                continue

            _stamp = (
                _receipt.get("uploaded_at")
                or _receipt.get("published_at")
            )
            if not _stamp:
                continue

            try:
                _when = datetime.fromisoformat(
                    str(_stamp).replace(
                        "Z",
                        "+00:00",
                    )
                )
                if _when.tzinfo is None:
                    _when = _when.replace(
                        tzinfo=timezone.utc,
                    )
                _when = _when.astimezone(
                    timezone.utc
                )
            except Exception:
                continue

            if (
                _latest_public is None
                or _when > _latest_public
            ):
                _latest_public = _when

        if _latest_public is not None:
            _elapsed = (
                datetime.now(timezone.utc)
                - _latest_public
            ).total_seconds()
            _remaining = (29 * 60) - _elapsed
            if _remaining > 0:
                print(
                    "YOUTUBE GLOBAL COOLDOWN:"
                    f" {int(_remaining + 0.999)}s"
                    f" remaining before {reel_id}",
                    flush=True,
                )
                _time.sleep(_remaining)

        youtube_result = (
            upload_to_youtube(
                video_path=output,
                metadata=metadata,
            )
        )

    metadata[
        "youtube"
    ] = youtube_result
